-- SQL is the sole schema authority. Apply only to a development Supabase project first.
begin;
create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to authenticated;
create type public.app_role as enum ('PLATFORM_ADMIN','ORG_ADMIN','ORGANIZER','MEMBER','RESTRICTED_MEMBER');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '' check(length(full_name)<=160),avatar_path text,status text not null default 'ACTIVE' check(status in ('ACTIVE','DISABLED')),created_at timestamptz not null default now());
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 1 and 160),created_at timestamptz not null default now());
create table public.organization_members(organization_id uuid not null references public.organizations,id uuid not null default gen_random_uuid() unique,user_id uuid not null references public.profiles,role public.app_role not null default 'MEMBER',state text not null default 'ACTIVE' check(state in ('ACTIVE','DISABLED')),created_at timestamptz not null default now(),primary key(organization_id,user_id));
create table public.invitations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,email text not null check(email=lower(email)),role public.app_role not null check(role<>'PLATFORM_ADMIN'),inviter_id uuid not null references public.profiles,expires_at timestamptz not null default now()+interval '7 days',status text not null default 'PENDING' check(status in ('PENDING','ACCEPTED','REVOKED')),delivery_status text not null default 'PENDING' check(delivery_status in ('PENDING','SENT','FAILED')),auth_user_id uuid references auth.users,created_at timestamptz not null default now());
create unique index invitation_pending_email on public.invitations(organization_id,email) where status='PENDING';
create table public.meetings(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,organizer_id uuid not null,title text not null check(length(title) between 1 and 200),description text not null default '' check(length(description)<=10000),agenda jsonb not null default '[]',starts_at timestamptz not null,ends_at timestamptz not null,timezone text not null default 'UTC',status text not null default 'SCHEDULED' check(status in ('SCHEDULED','LIVE','ENDED','CANCELLED')),room_name text not null unique default gen_random_uuid()::text,version integer not null default 1,created_at timestamptz not null default now(),unique(id,organization_id),foreign key(organization_id,organizer_id) references public.organization_members(organization_id,user_id),check(ends_at>starts_at and ends_at<=starts_at+interval '24 hours'));
create table public.meeting_members(meeting_id uuid not null,organization_id uuid not null,user_id uuid not null,meeting_role text not null default 'ATTENDEE' check(meeting_role in ('HOST','COHOST','ATTENDEE')),invitation_status text not null default 'PENDING' check(invitation_status in ('PENDING','ACCEPTED','DECLINED')),admitted_at timestamptz,removed_at timestamptz,primary key(meeting_id,user_id),foreign key(meeting_id,organization_id) references public.meetings(id,organization_id) on delete cascade,foreign key(organization_id,user_id) references public.organization_members(organization_id,user_id));
create table public.admission_requests(id uuid primary key default gen_random_uuid(),meeting_id uuid not null,user_id uuid not null,status text not null default 'PENDING' check(status in ('PENDING','APPROVED','REJECTED')),decided_by uuid references public.profiles,created_at timestamptz not null default now(),decided_at timestamptz,unique(meeting_id,user_id),foreign key(meeting_id,user_id) references public.meeting_members(meeting_id,user_id) on delete cascade);
create table public.meeting_presence(meeting_id uuid not null,user_id uuid not null,connected_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),primary key(meeting_id,user_id),foreign key(meeting_id,user_id) references public.meeting_members(meeting_id,user_id));
create table public.tasks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,meeting_id uuid,creator_id uuid not null references public.profiles,title text not null check(length(title) between 1 and 240),description text not null default '' check(length(description)<=10000),status text not null default 'To-do' check(status in ('To-do','On-going','On Review','Done')),priority text not null default 'Medium' check(priority in ('High','Medium','Low')),due_at timestamptz,archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id),foreign key(meeting_id,organization_id) references public.meetings(id,organization_id));
create table public.task_assignees(task_id uuid not null,organization_id uuid not null,user_id uuid not null,primary key(task_id,user_id),foreign key(task_id,organization_id) references public.tasks(id,organization_id) on delete cascade,foreign key(organization_id,user_id) references public.organization_members(organization_id,user_id));
create table public.task_comments(id uuid primary key default gen_random_uuid(),task_id uuid not null references public.tasks on delete cascade,author_id uuid not null references public.profiles,body text not null check(length(body) between 1 and 10000),created_at timestamptz not null default now());
create table public.task_checklist_items(id uuid primary key default gen_random_uuid(),task_id uuid not null references public.tasks on delete cascade,body text not null check(length(body) between 1 and 500),done boolean not null default false,position integer not null default 0);
create table public.folders(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,owner_id uuid not null references public.profiles,name text not null check(length(name) between 1 and 160),parent_id uuid,unique(id,organization_id),foreign key(parent_id,organization_id) references public.folders(id,organization_id));
create table public.documents(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,owner_id uuid not null references public.profiles,meeting_id uuid,folder_id uuid,name text not null check(length(name) between 1 and 240),storage_path text unique,mime_type text not null default 'text/plain',size bigint not null default 0 check(size between 0 and 26214400),kind text not null default 'document' check(kind in ('note','document','whiteboard','presentation')),body text not null default '' check(length(body)<=100000),upload_state text not null default 'READY' check(upload_state in ('PENDING','READY','FAILED')),deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id),foreign key(meeting_id,organization_id) references public.meetings(id,organization_id),foreign key(folder_id,organization_id) references public.folders(id,organization_id));
create table public.document_access(document_id uuid not null,organization_id uuid not null,user_id uuid not null,permission text not null check(permission in ('reader','editor')),primary key(document_id,user_id),foreign key(document_id,organization_id) references public.documents(id,organization_id) on delete cascade,foreign key(organization_id,user_id) references public.organization_members(organization_id,user_id));
create table public.favorites(document_id uuid not null references public.documents on delete cascade,user_id uuid not null references public.profiles,primary key(document_id,user_id));
create table public.message_threads(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,kind text not null check(kind in ('dm','group','meeting')),name text not null default '' check(length(name)<=160),meeting_id uuid unique,creator_id uuid not null references public.profiles,created_at timestamptz not null default now(),unique(id,organization_id),foreign key(meeting_id,organization_id) references public.meetings(id,organization_id),check((kind='meeting')=(meeting_id is not null)));
create table public.thread_members(thread_id uuid not null,organization_id uuid not null,user_id uuid not null,read_at timestamptz,last_message_at timestamptz,primary key(thread_id,user_id),foreign key(thread_id,organization_id) references public.message_threads(id,organization_id) on delete cascade,foreign key(organization_id,user_id) references public.organization_members(organization_id,user_id));
create table public.messages(id uuid primary key default gen_random_uuid(),thread_id uuid not null references public.message_threads on delete cascade,author_id uuid not null references public.profiles,body text not null check(length(body) between 1 and 10000),created_at timestamptz not null default now(),updated_at timestamptz,deleted_at timestamptz);
create table public.notes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,author_id uuid not null references public.profiles,meeting_id uuid,title text not null default '' check(length(title)<=240),body text not null default '' check(length(body)<=100000),visibility text not null default 'PRIVATE' check(visibility in ('PRIVATE','MEETING')),updated_at timestamptz not null default now(),unique(author_id,title),foreign key(meeting_id,organization_id) references public.meetings(id,organization_id));
create table public.notifications(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,user_id uuid not null references public.profiles,body text not null,target text not null,read_at timestamptz,created_at timestamptz not null default now());
create table public.audit_events(id bigint generated always as identity primary key,organization_id uuid references public.organizations,actor_id uuid references public.profiles,action text not null,resource_id uuid,details jsonb not null default '{}',created_at timestamptz not null default now());
create table public.calendar_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,owner_id uuid not null references public.profiles,title text not null check(length(title) between 1 and 200),starts_at timestamptz not null,ends_at timestamptz not null,timezone text not null default 'UTC',color text not null default 'blue',check(ends_at>starts_at));
create table public.calendar_preferences(user_id uuid primary key references public.profiles,preferences jsonb not null default '{}');
create table public.user_preferences(user_id uuid primary key references public.profiles,preferences jsonb not null default '{}');
create table private.rate_limits(actor_id uuid not null,key text not null,bucket timestamptz not null,hits integer not null default 1,primary key(actor_id,key,bucket));
create table private.media_operations(id uuid primary key default gen_random_uuid(),meeting_id uuid not null references public.meetings,user_id uuid,operation text not null check(operation in ('REMOVE','END','MUTE')),status text not null default 'PENDING' check(status in ('PENDING','DONE')),created_at timestamptz not null default now());
create index members_user on public.organization_members(user_id,state);
create index meetings_schedule on public.meetings(organization_id,starts_at);
create index meeting_members_user on public.meeting_members(user_id,meeting_id);
create index tasks_scope on public.tasks(organization_id,archived_at,updated_at desc);
create index task_assignees_user on public.task_assignees(user_id,task_id);
create index documents_scope on public.documents(organization_id,owner_id,deleted_at);
create index document_access_user on public.document_access(user_id,document_id);
create index thread_members_user on public.thread_members(user_id,thread_id);
create index messages_cursor on public.messages(thread_id,created_at desc,id);
create index notices_inbox on public.notifications(user_id,created_at desc);
create index audit_scope on public.audit_events(organization_id,created_at desc);
-- No application membership is created by signup. An invitation or manual bootstrap is mandatory.
create function private.create_profile() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,full_name) values(new.id,left(coalesce(new.raw_user_meta_data->>'full_name',''),160));return new;end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function private.create_profile();
revoke all on function private.create_profile() from public;
-- Roles stored in user_metadata never confer authority.
create function private.is_member(org uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.organization_members m join public.profiles p on p.id=m.user_id where m.organization_id=org and m.user_id=auth.uid() and m.state='ACTIVE' and p.status='ACTIVE' and (m.role in ('MEMBER','RESTRICTED_MEMBER') or auth.jwt()->>'aal'='aal2')) $$;
create function private.has_role(org uuid,roles public.app_role[]) returns boolean language sql stable security definer set search_path='' as $$ select private.is_member(org) and exists(select 1 from public.organization_members where organization_id=org and user_id=auth.uid() and role=any(roles)) $$;
create function private.is_host(mid uuid) returns boolean language sql stable security definer set search_path='' as $$ select auth.jwt()->>'aal'='aal2' and exists(select 1 from public.meeting_members mm where mm.meeting_id=mid and mm.user_id=auth.uid() and mm.meeting_role in ('HOST','COHOST') and mm.removed_at is null and private.is_member(mm.organization_id)) $$;
create function private.can_meeting(mid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.meeting_members where meeting_id=mid and user_id=auth.uid() and removed_at is null and private.is_member(organization_id)) $$;
create function private.can_task(tid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.tasks t where t.id=tid and private.is_member(t.organization_id) and (t.creator_id=auth.uid() or private.has_role(t.organization_id,array['PLATFORM_ADMIN','ORG_ADMIN','ORGANIZER']::public.app_role[]) or exists(select 1 from public.task_assignees a where a.task_id=t.id and a.user_id=auth.uid()))) $$;
create function private.can_document(did uuid,editing boolean default false) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.documents d where d.id=did and private.is_member(d.organization_id) and (d.owner_id=auth.uid() or d.deleted_at is null and d.upload_state='READY' and exists(select 1 from public.document_access a where a.document_id=d.id and a.user_id=auth.uid() and (not editing or a.permission='editor')))) $$;
create function private.can_thread(tid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.message_threads t where t.id=tid and private.is_member(t.organization_id) and (t.kind='meeting' and exists(select 1 from public.meeting_members m where m.meeting_id=t.meeting_id and m.user_id=auth.uid() and m.admitted_at is not null and m.removed_at is null) or t.kind<>'meeting' and exists(select 1 from public.thread_members m where m.thread_id=t.id and m.user_id=auth.uid()))) $$;
create function private.same_org(uid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.organization_members m where m.user_id=uid and private.is_member(m.organization_id)) $$;
revoke all on all functions in schema private from public;
grant execute on function private.is_member(uuid),private.has_role(uuid,public.app_role[]),private.is_host(uuid),private.can_meeting(uuid),private.can_task(uuid),private.can_document(uuid,boolean),private.can_thread(uuid),private.same_org(uuid) to authenticated;
-- All table writes go through scoped transactional functions. Direct REST writes are denied.
do $$ declare t text; begin foreach t in array array['profiles','organizations','organization_members','invitations','meetings','meeting_members','admission_requests','meeting_presence','tasks','task_assignees','task_comments','task_checklist_items','folders','documents','document_access','favorites','message_threads','thread_members','messages','notes','notifications','audit_events','calendar_events','calendar_preferences','user_preferences'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon, authenticated',t);execute format('grant select on public.%I to authenticated',t);end loop;end $$;
create policy profile_read on public.profiles for select to authenticated using(id=auth.uid() or private.same_org(id));
create policy org_read on public.organizations for select to authenticated using(private.is_member(id));
create policy member_read on public.organization_members for select to authenticated using(user_id=auth.uid() or private.is_member(organization_id));
create policy invitation_read on public.invitations for select to authenticated using(private.has_role(organization_id,array['PLATFORM_ADMIN','ORG_ADMIN']::public.app_role[]));
create policy meeting_read on public.meetings for select to authenticated using(private.can_meeting(id));
create policy meeting_member_read on public.meeting_members for select to authenticated using(private.can_meeting(meeting_id));
create policy admission_read on public.admission_requests for select to authenticated using(private.can_meeting(meeting_id) and (user_id=auth.uid() or private.is_host(meeting_id)));
create policy presence_read on public.meeting_presence for select to authenticated using(private.can_meeting(meeting_id));
create policy task_read on public.tasks for select to authenticated using(private.can_task(id));
create policy assignee_read on public.task_assignees for select to authenticated using(private.can_task(task_id));
create policy comment_read on public.task_comments for select to authenticated using(private.can_task(task_id));
create policy checklist_read on public.task_checklist_items for select to authenticated using(private.can_task(task_id));
create policy folder_read on public.folders for select to authenticated using(owner_id=auth.uid() and private.is_member(organization_id));
create policy document_read on public.documents for select to authenticated using(private.can_document(id));
create policy access_read on public.document_access for select to authenticated using(private.can_document(document_id));
create policy favorite_read on public.favorites for select to authenticated using(user_id=auth.uid() and private.can_document(document_id));
create policy thread_read on public.message_threads for select to authenticated using(private.can_thread(id));
create policy thread_member_read on public.thread_members for select to authenticated using(private.can_thread(thread_id));
create policy message_read on public.messages for select to authenticated using(private.can_thread(thread_id));
create policy note_read on public.notes for select to authenticated using(private.is_member(organization_id) and (author_id=auth.uid() or visibility='MEETING' and private.can_meeting(meeting_id)));
create policy notice_read on public.notifications for select to authenticated using(user_id=auth.uid() and private.is_member(organization_id));
create policy audit_read on public.audit_events for select to authenticated using(private.has_role(organization_id,array['PLATFORM_ADMIN','ORG_ADMIN']::public.app_role[]));
create policy event_read on public.calendar_events for select to authenticated using(owner_id=auth.uid() and private.is_member(organization_id));
create policy calendar_preference_read on public.calendar_preferences for select to authenticated using(user_id=auth.uid());
create policy user_preference_read on public.user_preferences for select to authenticated using(user_id=auth.uid());
commit;
